({
  _ensureInitialized() {
    if (!this.data || typeof this.data !== 'object') {
      this.data = {};
    }
    if (!this.data.bookmarks || typeof this.data.bookmarks !== 'object') {
      this.data.bookmarks = {};
    }
    if (typeof this.data.nextId !== 'number' || this.data.nextId < 1) {
      this.data.nextId = 1;
    }
  },

  _checkInvariants() {
    this.invariant(this.data && typeof this.data === 'object', 'Repository data must be an object');
    this.invariant(this.data.bookmarks && typeof this.data.bookmarks === 'object', 'Bookmarks store must be an object map');
    this.invariant(typeof this.data.nextId === 'number' && this.data.nextId >= 1, 'nextId must be a positive number');
    for (const [id, bm] of Object.entries(this.data.bookmarks)) {
      this.invariant(bm && typeof bm === 'object', `Bookmark entry for ${id} must be an object`);
      this.invariant(String(bm.id) === String(id), `Bookmark ID mismatch: expected ${id}, found ${bm.id}`);
      this.invariant(typeof bm.url === 'string' && bm.url.length > 0, `Bookmark ${id} must have a non-empty string URL`);
      this.invariant(typeof bm.title === 'string', `Bookmark ${id} title must be a string`);
      this.invariant(Array.isArray(bm.tags), `Bookmark ${id} tags must be an array`);
    }
  },

  async init(msg) {
    this._ensureInitialized();
    this._checkInvariants();
    return { initialized: true };
  },

  async addBookmark(msg) {
    this._ensureInitialized();

    const payload = (msg && msg.payload) || {};
    this.ensure(typeof payload.url === 'string' && payload.url.trim().length > 0, 'Precondition failed: url must be a non-empty string');
    this.ensure(payload.title === undefined || typeof payload.title === 'string', 'Precondition failed: title must be a string if provided');
    this.ensure(payload.tags === undefined || Array.isArray(payload.tags), 'Precondition failed: tags must be an array if provided');

    const id = String(this.data.nextId++);
    const normalizedTags = Array.isArray(payload.tags)
      ? payload.tags.map(t => String(t).trim()).filter(Boolean)
      : [];

    const now = new Date().toISOString();
    const bookmark = {
      id,
      url: payload.url.trim(),
      title: (payload.title || '').trim(),
      tags: normalizedTags,
      createdAt: now,
      updatedAt: now
    };

    this.data.bookmarks[id] = bookmark;
    this._checkInvariants();
    this.changed('bookmarkAdded', bookmark);

    this.ensure(this.data.bookmarks[id] !== undefined, 'Postcondition failed: bookmark must be saved in repository');
    this.ensure(this.data.bookmarks[id].id === id, 'Postcondition failed: saved bookmark must retain assigned ID');

    return bookmark;
  },

  async searchByTags(msg) {
    this._ensureInitialized();

    const payload = (msg && msg.payload) || {};
    this.ensure(Array.isArray(payload.tags), 'Precondition failed: tags must be an array');
    this.ensure(payload.matchAll === undefined || typeof payload.matchAll === 'boolean', 'Precondition failed: matchAll must be a boolean if provided');

    const targetTags = payload.tags.map(t => String(t).trim().toLowerCase()).filter(Boolean);
    const matchAll = Boolean(payload.matchAll);

    let results = [];
    const allBookmarks = Object.values(this.data.bookmarks);

    if (targetTags.length === 0) {
      results = allBookmarks.map(b => ({ ...b, tags: [...b.tags] }));
