      results = allBookmarks.filter(bm => {
        const itemTags = (bm.tags || []).map(t => String(t).trim().toLowerCase());
        if (matchAll) {
          return targetTags.every(tag => itemTags.includes(tag));
        } else {
          return targetTags.some(tag => itemTags.includes(tag));
        }
      }).map(b => ({ ...b, tags: [...b.tags] }));
    }

    this.ensure(Array.isArray(results), 'Postcondition failed: search result must be an array');
    return results;
  },

