    this.ensure(payload.url === undefined || (typeof payload.url === 'string' && payload.url.trim().length > 0), 'Precondition failed: url must be a non-empty string if provided');
    this.ensure(payload.title === undefined || typeof payload.title === 'string', 'Precondition failed: title must be a string if provided');
    this.ensure(payload.tags === undefined || Array.isArray(payload.tags), 'Precondition failed: tags must be an array if provided');

    const existing = this.data.bookmarks[id];

    if (payload.url !== undefined) {
      existing.url = payload.url.trim();
    }
    if (payload.title !== undefined) {
      existing.title = payload.title.trim();
    }
    if (payload.tags !== undefined) {
      existing.tags = payload.tags.map(t => String(t).trim()).filter(Boolean);
    }
    existing.updatedAt = new Date().toISOString();

    this._checkInvariants();
    this.changed('bookmarkUpdated', existing);

    this.ensure(this.data.bookmarks[id] !== undefined, 'Postcondition failed: updated bookmark must exist');
    this.ensure(this.data.bookmarks[id].id === id, 'Postcondition failed: bookmark id must not change');

    return { ...existing, tags: [...existing.tags] };
  },

  async deleteBookmark(msg) {
    this._ensureInitialized();

    const payload = (msg && msg.payload) || {};
    this.ensure(payload.id !== undefined && payload.id !== null, 'Precondition failed: bookmark id is required');

